// usage: probe reader <path> <seconds>
//        probe writer <path> <seconds>
func main() {
	mode, path := os.Args[1], os.Args[2]
	secs, _ := strconv.Atoi(os.Args[3])
	deadline := time.Now().Add(time.Duration(secs) * time.Second)

	switch mode {
	case "reader":
		var ok, enoent, other, zero int
		var otherErr string
		for time.Now().Before(deadline) {
			f, err := os.Open(path)
			if err == nil {
				st, serr := f.Stat()
				if serr == nil && st.Size() == 0 {
					zero++
				}
				ok++
				f.Close()
				continue
			}
			if errors.Is(err, fs.ErrNotExist) {
				enoent++
				continue
			}
			other++
			if otherErr == "" {
				otherErr = err.Error()
			}
		}
		fmt.Printf("reader opens=%d ok=%d ENOENT=%d zero_len=%d other=%d %s\n",
			ok+enoent+other, ok, enoent, zero, other, otherErr)
	case "writer":
		src, err := os.ReadFile(path)
		if err != nil {
			fmt.Println("writer: cannot seed:", err)
			os.Exit(1)
		}
		tmp := path + ".probetmp"
		n := 0
		for time.Now().Before(deadline) {
			if err := os.WriteFile(tmp, src, 0o644); err != nil {
				fmt.Println("writer WriteFile:", err)
				os.Exit(1)
			}
			// the exact syscall git uses at tempfile.c:347
			if err := syscall.Rename(tmp, path); err != nil {
				fmt.Println("writer Rename:", err)
				os.Exit(1)
			}
			n++
		}
		fmt.Printf("writer renames=%d\n", n)
	}
}
