package checkpoint

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// TestCollectChangedFiles_DoesNotRewriteUserIndex is the regression test for
// issue #2111: a repository-deleting commit, caused by this hook-path helper
// replacing the user's .git/index behind their back.
//
// `git status` is not a read. It refreshes the index's stat cache and, when
// anything is stale, writes the result back — builtin/commit.c takes
// .git/index.lock for the whole worktree walk and renames a fresh index over
// .git/index (tempfile.c, rename(2)). The replacement gives .git/index a new
// inode, and on a filesystem where rename-over-existing is not atomic against
// a concurrent lookup (measured on a virtiofs bind mount: 9.9% of opens during
// continuous replacement) a concurrent reader gets ENOENT. Git silently treats
// ENOENT on the index — and only ENOENT — as an empty index, so a `git commit`
// landing in that window records the empty tree with exit code 0 and no
// warning.
//
// Entire only ever wants the porcelain output, so the write is pure collateral
// and `--no-optional-locks` removes it with byte-identical output. This test
// asserts the file identity is preserved, which is the property that matters:
// no replacement means no window.
func TestCollectChangedFiles_DoesNotRewriteUserIndex(t *testing.T) {
	t.Parallel()

	repoDir := t.TempDir()
	testutil.InitRepo(t, repoDir)
	for _, name := range []string{"a.txt", "b.txt", "c.txt"} {
		testutil.WriteFile(t, repoDir, name, "initial\n")
		testutil.GitAdd(t, repoDir, name)
	}
	testutil.GitCommit(t, repoDir, "init")

	repo, err := gitrepo.OpenPath(repoDir)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}
	defer repo.Close()

	indexPath := filepath.Join(repoDir, ".git", "index")

	// Make the stat cache stale without changing content. This is the state git
	// writes the index back for, and it is the ordinary aftermath of an agent
	// turn, a formatter, or an editor save.
	staleTime := time.Now().Add(2 * time.Second)
	for _, name := range []string{"a.txt", "b.txt", "c.txt"} {
		if err := os.Chtimes(filepath.Join(repoDir, name), staleTime, staleTime); err != nil {
			t.Fatalf("chtimes %s: %v", name, err)
		}
	}

	before, err := os.Stat(indexPath)
	if err != nil {
		t.Fatalf("stat index before: %v", err)
	}

	if _, err := collectChangedFiles(context.Background(), repo); err != nil {
		t.Fatalf("collectChangedFiles: %v", err)
	}

	after, err := os.Stat(indexPath)
	if err != nil {
		t.Fatalf("stat index after: %v", err)
	}

	if !os.SameFile(before, after) {
		t.Error("collectChangedFiles replaced the user's .git/index (new inode); " +
			"the git status subprocess must pass --no-optional-locks so it never " +
			"takes index.lock or renames a new index into place (issue #2111)")
	}
	if !before.ModTime().Equal(after.ModTime()) {
		t.Errorf("collectChangedFiles rewrote the user's .git/index: mtime %v -> %v",
			before.ModTime(), after.ModTime())
	}
}

// TestCollectChangedFiles_IgnoresInheritedGitEnv proves the subprocess resolves
// the repository from cmd.Dir rather than from an inherited GIT_DIR.
//
// Git exports GIT_DIR (and sometimes GIT_WORK_TREE / GIT_INDEX_FILE) to its
// hooks, and those variables take precedence over the child's working
// directory — so a bare exec.Command inherits them and silently operates on
// the hook's repo instead of the one cmd.Dir names. The rest of the codebase
// strips them (gitrepo.EnvWithoutRepoOverrides); this call site did not.
func TestCollectChangedFiles_IgnoresInheritedGitEnv(t *testing.T) {
	repoDir := t.TempDir()
	testutil.InitRepo(t, repoDir)
	testutil.WriteFile(t, repoDir, "tracked.txt", "initial\n")
	testutil.GitAdd(t, repoDir, "tracked.txt")
	testutil.GitCommit(t, repoDir, "init")
	testutil.WriteFile(t, repoDir, "untracked.txt", "new\n")

	// A decoy repo, as a git hook's exported GIT_DIR would name.
	decoyDir := t.TempDir()
	testutil.InitRepo(t, decoyDir)
	testutil.WriteFile(t, decoyDir, "decoy.txt", "decoy\n")
	testutil.GitAdd(t, decoyDir, "decoy.txt")
	testutil.GitCommit(t, decoyDir, "decoy init")

	// Cannot be parallel: Setenv is process-global.
	t.Setenv("GIT_DIR", filepath.Join(decoyDir, ".git"))
	t.Setenv("GIT_WORK_TREE", decoyDir)
	t.Setenv("GIT_INDEX_FILE", filepath.Join(decoyDir, ".git", "index"))

	repo, err := gitrepo.OpenPath(repoDir)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}
	defer repo.Close()

	result, err := collectChangedFiles(context.Background(), repo)
	if err != nil {
		t.Fatalf("collectChangedFiles: %v", err)
	}

	found := false
	for _, f := range result.changedFiles {
		if f == "untracked.txt" {
			found = true
		}
		if f == "decoy.txt" {
			t.Errorf("collectChangedFiles resolved the decoy repo from the inherited "+
				"GIT_DIR instead of cmd.Dir; got files %v", result.changedFiles)
		}
	}
	if !found {
		t.Errorf("expected untracked.txt from the real repo, got %v", result.changedFiles)
	}
}

// TestGitStatusCallSitesPassNoOptionalLocks is the guard that keeps this fixed.
//
// This exact producer was diagnosed once before (ENT-242, Feb 2026) and the
// knowledge was lost: the PR that would have fixed it was closed unmerged, on
// the stated premise that `git status --porcelain -z` "reads without
// rewriting", and it would have grown the number of index-rewriting call sites
// from one to eleven. Nothing in the tree recorded the mitigation. A grep-level
// guard is cheap and survives that kind of turnover better than a comment.
func TestGitStatusCallSitesPassNoOptionalLocks(t *testing.T) {
	t.Parallel()

	root := repoRootForGuard(t)
	cmd := exec.Command("git", "grep", "-n", "--", `"git", "status"`, "--", "cmd", "internal") //nolint:noctx // guard test, no cancellation needed
	cmd.Dir = root
	out, err := cmd.Output()
	if err != nil {
		// git grep exits 1 when there are no matches, which would itself be a
		// surprise worth failing on.
		t.Fatalf("git grep for git status call sites failed: %v", err)
	}

	for _, line := range splitLines(string(out)) {
		if line == "" || isTestSourceLine(line) {
			continue
		}
		if !containsAny(line, `"--no-optional-locks"`, "NoOptionalLocks") {
			t.Errorf("git status invocation without --no-optional-locks: %s\n"+
				"`git status` rewrites the user's .git/index (issue #2111). Route it "+
				"through gitrepo.StatusCommand, or pass --no-optional-locks and "+
				"gitrepo.EnvWithoutRepoOverrides() explicitly.", line)
		}
	}
}

func repoRootForGuard(t *testing.T) string {
	t.Helper()
	cmd := exec.Command("git", "rev-parse", "--show-toplevel") //nolint:noctx // guard test, no cancellation needed
	out, err := cmd.Output()
	if err != nil {
		t.Skipf("not in a git checkout: %v", err)
	}
	return trimTrailingNewline(string(out))
}

